import{_ as p,B as r,o as i,c as h,a8 as o,d as u,w as d,f as n,E as a,af as g,a as t}from"./chunks/framework.CNIpabDg.js";const k=JSON.parse(`{"title":"Bindings","description":"Xila's graphics bindings connect guest WebAssembly imports to the context-provided graphics manager.","frontmatter":{"layout":"doc","docType":"explanation","description":"Xila's graphics bindings connect guest WebAssembly imports to the context-provided graphics manager."},"headers":[],"relativePath":"explanation/architecture/executables/bindings.md","filePath":"explanation/architecture/executables/bindings.md","lastUpdated":1793145952000}`),m={name:"explanation/architecture/executables/bindings.md"};function b(y,e,f,w,x,v){const l=r("Mermaid"),s=r("CodeReference"),c=r("HostReference");return i(),h("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793145952000"},[e[11]||(e[11]=o('<h1 id="bindings" tabindex="-1">Bindings <a class="header-anchor" href="#bindings" aria-label="Permalink to &quot;Bindings&quot;">​</a></h1><p>Xila&#39;s graphics bindings connect guest WebAssembly imports to the context-provided graphics manager. The shared LVGL catalog is generated in <code>subsystems/graphics/bindings_generator</code>; host dispatch and the Wasmi adapter live in <code>executables/wasm/src/host/graphics</code>.</p><h2 id="architecture-and-ownership" tabindex="-1">Architecture and ownership <a class="header-anchor" href="#architecture-and-ownership" aria-label="Permalink to &quot;Architecture and ownership&quot;">​</a></h2><ul><li><code>graphics_bindgen</code> discovers and orders the shared catalog. A build-time support registry filters guest wrappers and host metadata to implemented calls without renumbering legacy IDs; unsupported calls retain catalog IDs but are not generated as guest APIs. The registry emits a build-only JSON ABI inventory in <code>OUT_DIR</code>.</li><li>Guest wrappers import <code>xila_graphics_call</code>; <code>default_guest</code> also emits C wrappers and <code>xila_graphics.h</code> in the build output directory. Generation does not rewrite guest source files.</li><li><code>dispatch</code>, <code>objects</code>, and <code>marshal</code> use explicit graphics state and checked borrowed memory, without Wasmi types or global graphics-manager lookup.</li><li><code>graphics/wasmi.rs</code> handles store/memory access, import registration, and context capability checks.</li><li>VM-local object handles represent host objects. Deletion invalidates handles; issued handles are not reused within an execution. Teardown removes owned windows and children, including after traps.</li><li>Retained button-map strings and pointer tables are copied into VM-owned storage; guest memory growth or mutation cannot invalidate them. Label strings are copied synchronously by LVGL.</li></ul>',4)),(i(),u(g,null,{default:d(()=>[a(l,{id:"mermaid-41",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20Guest%20as%20Guest%20wrappers%0A%20%20%20%20participant%20Adapter%20as%20Wasmi%20graphics%20adapter%0A%20%20%20%20participant%20Dispatch%20as%20Checked%20dispatch%20and%20marshalling%0A%20%20%20%20participant%20Graphics%20as%20Context%20graphics%20manager%20%2F%20LVGL%0A%20%20%20%20Guest-%3E%3EAdapter%3A%20xila_graphics_call%0A%20%20%20%20Adapter-%3E%3EDispatch%3A%20Borrow%20guest%20memory%20and%20graphics%20state%0A%20%20%20%20Dispatch-%3E%3EDispatch%3A%20Validate%20signature%2C%20values%2C%20memory%20and%20handles%0A%20%20%20%20Dispatch-%3E%3EGraphics%3A%20Invoke%20supported%20API%20under%20manager%20lock%0A%20%20%20%20Graphics--%3E%3EDispatch%3A%20Result%0A%20%20%20%20Dispatch--%3E%3EGuest%3A%20Numeric%20status%20%2F%20translated%20output%0A"})]),fallback:d(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[12]||(e[12]=o('<h2 id="compatibility-and-supported-calls" tabindex="-1">Compatibility and supported calls <a class="header-anchor" href="#compatibility-and-supported-calls" aria-label="Permalink to &quot;Compatibility and supported calls&quot;">​</a></h2><p>The catalog requires guest and host bindings built from the same LVGL revision and configuration; call IDs are not a stable cross-version graphics ABI. Core now uses LVGL 9.6, including its updated event codes.</p><p>Calculator exercises the supported graphics subset; Weather still requires calls beyond it. The <a href="/reference/graphics-bindings.html#supported-calls">graphics reference</a> lists the exact operations and compatibility requirements.</p><p>Calls involving arbitrary native structure layouts, guest callbacks, retained guest pointers, raw LVGL fonts/styles, raw image assets or other unsupported LVGL functions are not offered as safe guest wrappers. <strong>Bounded Chart and Line widget adapters are now supported</strong>, with host-owned typed data rather than native guest pointers. Unsupported numeric IDs still return an unsupported status. Guest memory is never interpreted as a typed host reference.</p><h2 id="extended-widget-surface-core-488-and-489" tabindex="-1">Extended widget surface (Core #488 and #489) <a class="header-anchor" href="#extended-widget-surface-core-488-and-489" aria-label="Permalink to &quot;Extended widget surface (Core #488 and #489)&quot;">​</a></h2><p>The generated host-dispatched graphics surface now contains <strong>133 calls</strong> (out of 1,088 surveyed catalog calls in this configuration). Range/toggle adapters include Arc, Bar, Slider, Switch and Spinner with checked values, ranges, orientation/state, and bounded animation parameters. The next slice adds Calendar, Spinbox, Chart, Line, List and Tileview along with Shadcn Badge/Card/button-variant/Input-error helpers.</p><p>Calendar highlights, Line points and Chart series data are host-owned. Chart series are scoped IDs rather than native pointers, and Tileview returns checked child handles. There is no unrestricted host heap or automatic guest-pointer retention: per-widget and per-VM budgets apply. However, this <strong>does not</strong> expose every enabled LVGL widget, arbitrary images or automatic ABI version negotiation. See <a href="/reference/graphics-bindings.html#resource-limits">resource limits</a>.</p><h2 id="layout-and-semantic-styling" tabindex="-1">Layout and semantic styling <a class="header-anchor" href="#layout-and-semantic-styling" aria-label="Permalink to &quot;Layout and semantic styling&quot;">​</a></h2><p>The merged graphics ABI covers scalar object geometry, built-in Flex/Grid layouts, validated grid track arrays and cell placement, local RGB888 style properties, four semantic theme surfaces and six host-owned ROM font roles. Grid arrays are copied into host-owned allocations rather than retained in guest memory (31 tracks per axis, 512 retained descriptors per VM). A guest receives checked IDs instead of raw <code>lv_style_t</code> or <code>lv_font_t</code> pointers. This remains a partial LVGL surface; other widgets and ABI capability/version negotiation are follow-up work.</p><h2 id="bounded-state" tabindex="-1">Bounded state <a class="header-anchor" href="#bounded-state" aria-label="Permalink to &quot;Bounded state&quot;">​</a></h2><p>Object handles and retained map strings have fixed limits so an execution&#39;s host-side state remains bounded. Handles are local to the VM and never reused during that execution; this prevents a deleted object&#39;s identity from granting access to a later object. The <a href="/reference/graphics-bindings.html#resource-limits">reference</a> gives capacities and numeric status codes.</p><h2 id="extension-points-and-validation" tabindex="-1">Extension points and validation <a class="header-anchor" href="#extension-points-and-validation" aria-label="Permalink to &quot;Extension points and validation&quot;">​</a></h2><p>Extend the shared catalog and checked dispatch together, and keep the Wasmi adapter thin. Validate memory and handle behavior before adding a supported call. Native adapter and lifetime tests exercise cleanup; the portable translation tests separately cover guest-memory boundaries and word widths.</p><h2 id="exact-boundary-between-generation-and-runtime" tabindex="-1">Exact boundary between generation and runtime <a class="header-anchor" href="#exact-boundary-between-generation-and-runtime" aria-label="Permalink to &quot;Exact boundary between generation and runtime&quot;">​</a></h2><p>Graphics bindings are generated from a shared LVGL catalog in <code>subsystems/graphics/bindings_generator</code>, but <strong>the Wasmi executable</strong> owns guest memory translation, handle tables and host dispatch. A generated function ID is not an unrestricted LVGL function pointer. The generated host <code>Function</code> table contains signatures and supported-call metadata from the shared build-time registry; the guest and host must use matching LVGL versions and generated catalogs.</p><p><code>host/graphics/wasmi.rs</code> installs exactly one graphics entrypoint under the import pair <code>(&quot;host&quot;, &quot;xila_graphics_call&quot;)</code>. Each invocation supplies a function ID, <strong>up to seven machine-word arguments</strong>, the argument count and a result address. Before dispatch, the adapter checks that the current <code>ExecutableContext.graphics_manager</code> is the manager granted to that VM and obtains the current Wasmi linear memory view.</p><p><code>dispatch</code> checks the function ID, expected argument count, result pointer, handle kinds and value domains, then takes the Graphics lock before calling supported LVGL operations. Missing graphics capabilities or unsupported calls return explicit numeric error statuses rather than granting direct host pointers.</p><h2 id="memory-object-and-retained-string-limits" tabindex="-1">Memory, object and retained-string limits <a class="header-anchor" href="#memory-object-and-retained-string-limits" aria-label="Permalink to &quot;Memory, object and retained-string limits&quot;">​</a></h2><p>The graphics bridge stores VM-local object capabilities in a bounded <code>GraphicsState</code>. It allows <strong>256 object slots</strong>, assigning monotonically increasing nonzero handles. Deletion invalidates the object without reassigning that handle to another object in the same VM. A graphics object is tied to a window tree; VM teardown deletes owned windows and releases retained maps/canvases.</p><p><code>GuestMemory</code> decodes little-endian ABI values by value and validates address ranges with checked multiplication and addition. No Rust references into guest linear memory may survive a guest-memory growth or a host async suspension. Typed values are not reconstructed with unchecked host-native struct layout.</p><p>The current marshaller has explicit limits:</p><ul><li><strong>Object slots:</strong> 256 per VM.</li><li><strong>Ordinary NUL-terminated strings:</strong> 1,024 bytes including the terminator.</li><li><strong>Textarea strings:</strong> 4,097 bytes including the terminator.</li><li><strong>Button-map entries:</strong> 64, counting the end sentinel.</li><li><strong>Retained button-map storage:</strong> 8,192 bytes including strings and sentinel.</li></ul><p>Button-map strings and pointer arrays are <strong>copied into stable VM-owned host storage</strong> before LVGL retains them. Ordinary label text is copied synchronously by LVGL. Unsupported native callback pointers and arbitrary binary structure layouts remain outside the guest API.</p><h2 id="extending-safely" tabindex="-1">Extending safely <a class="header-anchor" href="#extending-safely" aria-label="Permalink to &quot;Extending safely&quot;">​</a></h2><p>Add the function signature to the shared catalog, implement checked dispatch, then update the guest wrapper generation and tests. Preserve unsupported IDs when changing the catalog to avoid accidental renumbering, but <strong>do not promise binary compatibility across independently built LVGL revisions</strong>.</p><p>Run host-side object deletion tests and guest memory32/memory64 translation tests; verify handle invalidation, bad pointer rejection, event-queue cleanup and resource-cap enforcement before considering a new binding supported.</p><h3 id="source-references" tabindex="-1">Source references <a class="header-anchor" href="#source-references" aria-label="Permalink to &quot;Source references&quot;">​</a></h3>',27)),t("ul",null,[t("li",null,[a(s,{path:"subsystems/graphics/bindings_generator"}),e[1]||(e[1]=n(" — API catalog and function selection.",-1))]),t("li",null,[a(s,{repo:"applications",path:"executables/wasm/src/host/graphics/wasmi.rs"}),e[2]||(e[2]=n(" — Wasmi import registration.",-1))]),t("li",null,[a(s,{repo:"applications",path:"executables/wasm/src/host/graphics/dispatch.rs"}),e[3]||(e[3]=n(" — checked host dispatch.",-1))]),t("li",null,[a(s,{repo:"applications",path:"executables/wasm/src/host/graphics/objects.rs"}),e[4]||(e[4]=n(" — VM-local object registry.",-1))]),t("li",null,[a(s,{repo:"applications",path:"executables/wasm/src/host/graphics/marshal.rs"}),e[5]||(e[5]=n(" — retained strings and map bounds.",-1))]),t("li",null,[a(s,{repo:"applications",path:"executables/wasm/src/host/translation/memory.rs"}),e[6]||(e[6]=n(" — borrowed guest-memory view.",-1))]),e[7]||(e[7]=t("li",null,[t("a",{href:"/reference/graphics-bindings.html"},"Bindings reference"),n(" — supported call list and status codes.")],-1))]),e[13]||(e[13]=t("h2",{id:"references-see-also",tabindex:"-1"},[n("References / See also "),t("a",{class:"header-anchor",href:"#references-see-also","aria-label":'Permalink to "References / See also"'},"​")],-1)),t("ul",null,[t("li",null,[a(s,{path:"subsystems/graphics/bindings_generator"})]),t("li",null,[a(s,{repo:"applications",path:"executables/wasm/src/host/graphics"})]),t("li",null,[a(s,{repo:"applications",path:"executables/wasm/tests/translation/README.md"})]),t("li",null,[a(c,{repo:"applications",crate:"wasm"})]),e[8]||(e[8]=t("li",null,[t("a",{href:"/explanation/architecture/subsystems/graphics.html"},"Graphics")],-1)),e[9]||(e[9]=t("li",null,[t("a",{href:"/explanation/architecture/executables/wasm.html"},"WASM runtime")],-1)),e[10]||(e[10]=t("li",null,[t("a",{href:"/explanation/architecture/libraries/abi.html"},"ABI")],-1))])])}const L=p(m,[["render",b]]);export{k as __pageData,L as default};
